import {
  AdvancedCardDialogManager,
  CardToolbarAction,
  CardUIExtension,
  ICardModel,
  ICardUIExtensionContext,
  VirtualSchemePresenter
} from 'tessa/ui/cards';
import {
  AutoCompleteEntryViewModel,
  AutoCompleteTableViewModel,
  ButtonViewModel,
  DateTimeViewModel,
  DecimalBoxViewModel,
  FileListViewModel,
  FilePreviewViewModel,
  GridRowAction,
  GridViewModel,
  RowAutoCompleteItem,
  TextBoxViewModel
} from 'tessa/ui/cards/controls';
import {
  createCardEditorModel,
  createDialogForm,
  FormCreationOptions,
  LoadingOverlay,
  MenuAction,
  showConfirmWithCancel,
  showError,
  showLoadingOverlay,
  showMessage,
  showNotEmpty,
  tryGetFromInfo,
  tryGetFromSettings,
  UIButton,
  UIContext
} from 'tessa/ui';
import {
  createTypedField,
  deepClone,
  DotNetType,
  TypedField,
  unseal,
  Visibility
} from 'tessa/platform';
import { showDialog } from 'tessa/ui/uiHost';
import { MetadataStorage } from 'tessa';
import { CardTypeSection, systemKeyPrefix } from 'tessa/cards';
import { getTessaIcon } from 'common/utility';
import { CardRequest, CardResponse, CardService } from 'tessa/cards/service';
import { ValidationKey, ValidationResultType } from 'tessa/platform/validation';
import { CardTableViewControlViewModel } from '../ui/tableViewExtension/cardTableViewControlViewModel';
import { CardTableViewRowData } from '../ui/tableViewExtension/cardTableViewRowData';
import { reaction } from 'mobx';
import { DefaultFormTabWithTasksViewModel } from 'tessa/ui/cards/forms';
import { CustomStyle } from 'tessa/ui/cards/customElementStyle';
import { getFileViewExtensionInitializationStrategyHandlers } from '../ui/cardFiles/cardFilesExtensions';
import { AbCustomFilesViewCardControlInitializationStrategy } from './abCustomFilesViewCardControlInitializationStrategy';
import { FilesViewControlContentItemsFactory } from '../ui/cardFiles/filesViewControlContentItemsFactory';
import { HttpError, extension, inject, localize } from '@tessa/application';
import {
  CardTypeSectionColumn,
  ICardTypeExtensionContext,
  SchemeGuids,
  SchemeTableContentType,
  SchemeType
} from '@tessa/platform';
import { Base64Helper, Guid, IStorage, StorageHelper, ValidationResult } from '@tessa/core';
import { AbTestServiceClient, AbTestServiceClient$ } from './abTestServiceClient';
import { IPreviewerViewModel } from 'tessa/ui/preview';
import { PdfPreviewerViewModel } from 'tessa/ui/preview/pdf/pdfPreviewerViewModel';
import { Alert, AlertType } from 'tessa/ui/alerts';

@extension({ name: 'AbCarUIExtension' })
export class AbCarUIExtension extends CardUIExtension {
  private _disposes: Array<(() => void) | null> = [];
  private _syncPageEvents: Array<() => void> = [];

  constructor(@inject(AbTestServiceClient$) private readonly _serviceClient: AbTestServiceClient) {
    super();
  }

  public initializing(context: ICardUIExtensionContext): void {
    getFileViewExtensionInitializationStrategyHandlers(context.model)?.push(
      (ctx: ICardTypeExtensionContext, _m: ICardModel) => {
        const settings = ctx.settings;
        const filesViewAlias = tryGetFromSettings<string>(settings, 'FilesViewAlias', '');
        return filesViewAlias === 'AllFilesControl'
          ? new AbCustomFilesViewCardControlInitializationStrategy(
              new FilesViewControlContentItemsFactory()
            )
          : null;
      }
    );
  }

  public initialized(context: ICardUIExtensionContext): void {
    const cardModel = context.model;
    const imageFileControl = tryGetFromInfo<FileListViewModel | null>(
      cardModel.info,
      'ImageFilesControl',
      null
    );

    // показываем файлы только с категорией Image

    if (imageFileControl) {
      imageFileControl.removeFiles(
        file => !(file.model.category && file.model.category.caption === 'Image')
      );

      this._disposes.push(
        imageFileControl.containerFileAdding.addWithDispose(e => {
          if (!(e.file.category && e.file.category.caption === 'Image')) {
            e.cancel = true;
          }
        })
      );
    }

    const discountPrice = cardModel.controls.get('Discount') as DecimalBoxViewModel;
    if (discountPrice) {
      discountPrice.buttonsContainer.addButton(
        UIButton.create({
          name: 'Discount',
          icon: 'm-refresh',
          theme: 'control',
          type: 'small',
          buttonAction: () => {
            const sec = cardModel.card.sections.get('AbCarMainInfo');
            const origPrice = parseFloat(sec.fields.get<string>('Cost') ?? '0');
            if (origPrice === 0) {
              showMessage("You haven't set up an initial cost yet 😔");
              return;
            }

            const resultingCost = origPrice - origPrice * 0.2;
            showMessage(
              `Congratulations! You found our special discount 🥳
              The resulting price for you will be ${resultingCost}`
            );
            sec.fields.set('DiscountCost', TypedField.createDecimal(resultingCost.toString()));
          }
        })
      );
    }

    // показываем файлы без категории Image
    const allFilesControl = tryGetFromInfo<FileListViewModel | null>(
      cardModel.info,
      'AllFilesControl',
      null
    );
    if (allFilesControl) {
      allFilesControl.removeFiles(
        file => !!file.model.category && file.model.category.caption === 'Image'
      );

      this._disposes.push(
        allFilesControl.containerFileAdding.addWithDispose(e => {
          if (e.file.category && e.file.category.caption === 'Image') {
            e.cancel = true;
          }
        })
      );
    }

    // запрещаем добавлять файлы с расширением .exe
    this._disposes.push(
      context.fileContainer.containerFileChanging.addWithDispose(async e => {
        const file = e.added;
        if (file && file.getExtension() === 'exe') {
          await showMessage("Can't add file: " + file.name);
          e.cancel = true;
        }
      })
    );

    const driverControl = context.model.controls.get('DriverName2') as AutoCompleteEntryViewModel;
    if (driverControl) {
      driverControl.useUserInfoTooltip = true;

      driverControl.valueSet.add(args =>
        Alert.show({
          text: 'Demo for event ValueSelected. Selected item: ' + args.item.displayText
        })
      );

      driverControl.valueDeleted.add(args =>
        Alert.show({
          text: 'Demo for event ValueDeleted. Deleted item: ' + args.item.displayText
        })
      );

      driverControl.openCardCommand.func = async () => {
        if (!driverControl.item || driverControl.item.reference == undefined) {
          return;
        }

        const info = {};
        info['.autocomplete'] = driverControl.getRefInfo();

        await cardModel.executeInContext(async uiContext => {
          await showLoadingOverlay(async splashResolve => {
            await AdvancedCardDialogManager.instance.openCard({
              cardId: driverControl.item!.reference,
              context: uiContext,
              info,
              splashResolve
            });
          });
        });
      };
    }

    const ownersControl = context.model.controls.get('Owners') as AutoCompleteTableViewModel;
    if (ownersControl) {
      this._disposes.push(
        ownersControl.valueSet.addWithDispose(e => {
          const items = e.autocomplete.items as RowAutoCompleteItem[];
          const minOrder = Math.min(...items.map(x => x.order));
          const firstItem = items.find(x => x.order === minOrder);
          if (!firstItem) {
            return;
          }
          const displayText: string = firstItem.row.get('UserName')!;
          if (!displayText.endsWith(' (*)')) {
            firstItem.row.rawSet(
              'UserName',
              createTypedField(`${displayText} (*)`, DotNetType.String)
            );
          }
        })
      );
    }

    const carNameControl = context.model.controls.get('CarName');
    if (carNameControl) {
      carNameControl.hasActiveValidation = true;
      carNameControl.validationFunc = c => {
        if ((c as TextBoxViewModel).text === '42') {
          return "Can't enter magic number here";
        }

        return null;
      };
    }

    const preview1 = context.model.controls.get('Preview1') as FilePreviewViewModel;
    const preview2 = context.model.controls.get('Preview2') as FilePreviewViewModel;

    if (preview1 && preview2) {
      // если в каком-либо превью меняется вью-модель средства, необходимо заново их связать.
      const preview1ReactionDispose = reaction(
        () => preview1.fileControlManager.previewerViewModel,
        viewModel1 => {
          this.setPageSyncEvents(viewModel1, preview2.fileControlManager.previewerViewModel);
        }
      );

      const preview2ReactionDispose = reaction(
        () => preview2.fileControlManager.previewerViewModel,
        viewModel2 => {
          this.setPageSyncEvents(preview1.fileControlManager.previewerViewModel, viewModel2);
        }
      );

      this._disposes.push(preview1ReactionDispose, preview2ReactionDispose);

      this.setPageSyncEvents(
        preview1.fileControlManager.previewerViewModel,
        preview2.fileControlManager.previewerViewModel
      );
    }

    // Добавляем тестовую кнопку в тулбар.
    // Кнопка отображается в карточке, открытой во вкладке и в диалоге.
    // Если необходимо отображать кнопку, например, только во вкладке, то надо добавить условие:
    // !!context.dialogName
    if (context.toolbar && context.uiContext?.cardEditor) {
      const title = 'TestButton';
      context.toolbar.removeItemIfExists(title);

      context.toolbar.addItem(
        new CardToolbarAction({
          name: title,
          caption: 'Test Button',
          icon: getTessaIcon('Thin285'),
          command: () => {
            showMessage('Test button was pressed.');
          }
        })
      );

      context.toolbar.removeItemIfExists('PreviewInDialog');
      context.toolbar.addItem(
        new CardToolbarAction({
          name: 'PreviewInDialog',
          caption: cardModel.previewManager.showInDialogByDefault
            ? 'Default Preview'
            : 'Preview In Dialog',
          icon: getTessaIcon('Thin8'),
          command: item => {
            const previewInDialog = !cardModel.previewManager.showInDialogByDefault;
            cardModel.previewManager.showInDialogByDefault = previewInDialog;
            item.caption = previewInDialog ? 'Default Preview' : 'Preview In Dialog';
          }
        })
      );

      const cardId = cardModel.card.id;
      context.toolbar.removeItemIfExists('CarTableRequest');
      context.toolbar.addItem(
        new CardToolbarAction({
          name: `CarTableRequest`,
          caption: '$UI_Controls_CarTableRequest',
          icon: getTessaIcon('Thin114'),
          command: async () => {
            // Вызвать окно подтверждения.
            const result = await showConfirmWithCancel('$AbTest_CarTableRequestConfirmation');

            // Если нажали кнопку "Отмена", ничего делать не надо.
            if (result !== null) {
              await this.executeCarTableRequest(cardId, result);
            }
          }
        })
      );
    }

    const requestExternalSystemButton = context.model.controls.get(
      'RequestExternalSystemButton'
    ) as ButtonViewModel;
    if (requestExternalSystemButton) {
      requestExternalSystemButton.onClick = this.get1CfileAsync;
      requestExternalSystemButton.isReadOnly = !context.model.fileContainer.permissions.canAdd;
    }

    // Использование апи выставления поворотов
    // this._disposes.push(
    //   preview1.fileControlManager.rotateChanged.addWithDispose(
    //     (args: { fileVersionId: string; page: number; angle: number }) => {
    //       const version = preview2.fileControlManager.fileVersion;
    //       if (!version) {
    //         return;
    //       }
    //       preview2.fileControlManager.setRotateAngle(
    //         version.id,
    //         preview2.fileControlManager.pageNumber,
    //         args.angle
    //       );
    //     }
    //   )!
    // );

    // Использование апи масштабирования
    // this._disposes.push(
    //   preview1.fileControlManager.scaleChanged.addWithDispose(
    //     (args: { fileVersionId: string; scale: ScaleOption; customScaleValue: number }) => {
    //       preview2.fileControlManager.setScale(args.scale, args.customScaleValue);
    //     }
    //   )!
    // );

    const datePickerViewModel = context.model.controls.get('ReleaseDate') as DateTimeViewModel;
    if (datePickerViewModel) {
      datePickerViewModel.onCalendarMonthSelection = async ctx => {
        const { days, modifiedDays } = ctx;

        days
          .filter(dayOfMonth => dayOfMonth.day() === 2)
          .map(day => ({
            day: day.format(),
            className: 'calendar-day-danger',
            classNameSelected: 'calendar-day-danger-selected'
          }))
          .forEach(day => modifiedDays.push(day));
        return modifiedDays;
      };

      // В контрол выбора DateTimePicker устанавливаются настройки автоподстановки даты.
      // С их помощью можно автоматически подставлять значения даты, указанные в настройках, в контрол.
      datePickerViewModel.autoCompleteInfo = {
        year: 2024,
        month: 7,
        day: 3
        // Также можно указать и значения времени.
        /*hours: 1,
        minutes: 30,
        seconds: 40,
        timeDesignator: 'AM'*/
      };
    }

    const showDialogTypeFormButton = cardModel.controls.get(
      'ShowDialogTypeForm'
    ) as ButtonViewModel;
    if (showDialogTypeFormButton) {
      showDialogTypeFormButton.onClick = async () => {
        const virtualSchemeDialog = MetadataStorage.instance.cardMetadata.cardTypes.getCardTypeById(
          'b2b4d2c2-8f92-4262-9951-fe1a64bf9b30'
        ); // VirtualSchemeCardTypeID
        const virtualSchemeDialogClone = deepClone(virtualSchemeDialog)!;

        const generalSection = new CardTypeSection();
        generalSection.id = SchemeGuids.instances;
        generalSection.name = 'Instances';
        generalSection.description = 'Fake Instances';
        generalSection.tableType = SchemeTableContentType.Enumeration;

        const idColumn = new CardTypeSectionColumn();
        idColumn.schemeType = SchemeType.Guid;
        idColumn.id = SchemeGuids.instances_ID;
        idColumn.name = 'ID';
        idColumn.description = 'Column from fake instances';
        generalSection.columns.push(idColumn);

        const presenter = new VirtualSchemePresenter(
          unseal<CardTypeSection[]>(virtualSchemeDialogClone.cardTypeSections),
          [generalSection]
        );
        const form = await presenter.createForm();
        if (!form) {
          showError('Dialog type "VirtualScheme" not found.');
          return;
        }

        await showDialog(
          form,
          null,
          [
            UIButton.create({
              caption: '$UI_Common_Close',
              buttonAction: btn => btn.close(),
              type: 'normal',
              theme: 'secondary'
            })
          ],
          {
            hideTopCloseIcon: true,
            backgroundHolder: true
          }
        );
      };
    }

    // в контроле-таблице "Список акций"
    const grid = context.model.controls.get('ShareList') as GridViewModel;
    if (grid) {
      grid.rowInitializing.add(async e => {
        const rowFormContext = e.cardModel.currentRow?.rowFormContext;
        if (!rowFormContext) {
          return;
        }

        // Кнопка видна всегда
        const testDialogButton = UIButton.create({
          caption: 'Test',
          theme: 'primary',
          type: 'normal',
          name: 'testButton',
          buttonAction: () => {
            Alert.show({ text: 'Test !', type: AlertType.Info });
          }
        });

        // Кнопка будет видна если есть ошибка
        const testDialogButtonError = UIButton.create({
          caption: 'Error',
          theme: 'red',
          type: 'normal',
          name: 'testButtonError',
          visibility: () =>
            rowFormContext.hasValidationErrors ? Visibility.Visible : Visibility.Hidden,
          buttonAction: () => {
            Alert.show({ text: 'Test error !', type: AlertType.Error });
          }
        });

        rowFormContext.buttonsRowDialog.push(testDialogButton);
        rowFormContext.buttonsRowDialog.push(testDialogButtonError);
      });

      // добавляем валидацию при сохранении редактируемой строки
      this._disposes.push(
        grid.rowValidating.addWithDispose(e => {
          if (!e.row.get('Name') || e.row.get('Name') === '') {
            e.validationResult.add(
              ValidationKey.unknown,
              ValidationResultType.Error,
              "Share's name is empty (from RowValidating)."
            );
          }
        }),
        // нажатие Ctrl+Enter показывает окно для выбранной строки в фокусе
        grid.keyDown.addWithDispose(e => {
          const code = e.event.keyCode || e.event.charCode;
          if (code === 13 && e.event.ctrlKey) {
            e.event.stopPropagation();
            e.event.preventDefault();

            const gridViewModel = e.control as GridViewModel;

            if (gridViewModel.selectedRow) {
              showMessage(`Share name is ${gridViewModel.selectedRow.row.get('Name')}`);
            }
          }
        }),
        // при открытии окна добавления/редактирования строки добавляем горячую клавишу
        grid.keyDown.addWithDispose(e => {
          const code = e.event.keyCode || e.event.charCode;
          if (code === 116) {
            // f5
            e.event.stopPropagation();
            e.event.preventDefault();
            showMessage('F5 key is pressed');
          }
        }),
        // при клике по ячейке из первой колонки "Акция" в открытом окне будет поставлен фокус
        // на первый контрол типа "Строка", в котором также будет выделен весь текст
        grid.rowInitialized.addWithDispose(e => {
          if (e.action === GridRowAction.Opening && e.columnIndex === 0) {
            const textBox = e.rowModel?.controlsBag.find(
              x => x instanceof TextBoxViewModel
            ) as TextBoxViewModel;
            if (textBox) {
              textBox.focus();
              textBox.selectAll();
            }
          }
        })
      );

      // контекстное меню таблицы, зависит от кликнутой ячейки
      grid.contextMenuGenerators.push(ctx => {
        const text = `Name=${ctx.row.row.get('Name')}, Count=${
          ctx.control.selectedRows.length
        }, Cell="${ctx.cell?.value}"`;

        ctx.menuActions.push(
          MenuAction.create({
            type: 'normal',
            name: 'Name',
            caption: text,
            action: () => {
              showMessage(`Share name is ${ctx.row.row.get('Name')}`);
            }
          }),
          MenuAction.create({
            type: 'normal',
            name: 'EditRow',
            caption: 'Edit row',
            icon: getTessaIcon('Thin2'),
            action: async () => {
              await grid.editRow(ctx.row, ctx.columnIndex);
            }
          })
        );
      });
    }

    const shareListView = context.model.controls.get(
      'ShareListView'
    ) as CardTableViewControlViewModel;
    if (shareListView) {
      shareListView.rowInitializing.add(e => {
        const rowFormContext = e.cardModel.currentRow?.rowFormContext;

        if (!rowFormContext) {
          return;
        }

        // Кнопка видна всегда
        const testDialogButon = UIButton.create({
          caption: 'Test',
          theme: 'primary',
          type: 'normal',
          name: 'testButton',
          buttonAction: () => {
            alert('Test !');
          }
        });

        // Кнопка будет видна если есть ошибка
        const testDialogButonError = UIButton.create({
          caption: 'Error',
          theme: 'red',
          type: 'normal',
          name: 'testButtonError',
          visibility: () =>
            rowFormContext.hasValidationErrors ? Visibility.Visible : Visibility.Hidden,
          buttonAction: () => {
            alert('Test error !');
          }
        });

        rowFormContext.buttonsRowDialog.push(testDialogButon);
        rowFormContext.buttonsRowDialog.push(testDialogButonError);
      });

      // добавляем валидацию при сохранении редактируемой строки
      this._disposes.push(
        shareListView.rowValidating.addWithDispose(e => {
          if (!e.row.get('Name')) {
            e.validationResult.add(
              ValidationKey.unknown,
              ValidationResultType.Error,
              "Share's name is empty (from RowValidating)."
            );
          }
        }),
        // при клике по ячейке из первой колонки "Акция" в открытом окне будет поставлен фокус
        // на первый контрол типа "Строка", в котором также будет выделен весь текст
        shareListView.rowInitialized.addWithDispose(e => {
          // e.Cell всегда null, если ViewSelectionMode.Row
          if (e.action === GridRowAction.Opening && e.cell?.column.columnName === '0') {
            const textBox = e.rowModel?.controlsBag.find(
              x => x instanceof TextBoxViewModel
            ) as TextBoxViewModel;
            if (textBox) {
              textBox.focus();
              textBox.selectAll();
            }
          }
        })
      );

      // контекстное меню таблицы, зависит от кликнутой ячейки
      if (shareListView.table) {
        this._disposes.push(
          // при открытии окна добавления/редактирования строки добавляем горячую клавишу
          shareListView.table.keyDown.addWithDispose(e => {
            const code = e.event.keyCode || e.event.charCode;
            if (code === 116) {
              // f5
              e.event.stopPropagation();
              e.event.preventDefault();
              showMessage('F5 key is pressed');
            }
          }),
          // нажатие Ctrl+Enter показывает окно для выбранной строки в фокусе
          shareListView.table.keyDown.addWithDispose(e => {
            const code = e.event.keyCode || e.event.charCode;
            if (code === 13 && e.event.ctrlKey) {
              const selectedRow = e.control.viewComponent.selectedRow;

              e.event.stopPropagation();
              e.event.preventDefault();
              showMessage(`Share name is ${selectedRow?.get('Name')}`);
            }
          })
        );

        shareListView.table?.rowContextMenuGenerators?.push(ctx => {
          const data = ctx.row.data as CardTableViewRowData;
          // e.Cell всегда null, если ViewSelectionMode.Row
          const text = `Name=${data.get('0')}, Count=${
            ctx.tableGrid.viewComponent.selectedRows?.length
          }, Cell="${ctx.cell?.value ?? ctx.cell?.convertedValue}"`;

          ctx.menuActions.push(
            MenuAction.create({
              type: 'normal',
              name: 'Name',
              caption: text,
              action: () => {
                showMessage(`Share name is ${data.get('0')}`);
              }
            }),
            MenuAction.create({
              type: 'normal',
              name: 'EditRow',
              caption: 'Edit row',
              icon: getTessaIcon('Thin2'),
              action: async () => {
                await shareListView.editRow(ctx.row);
              }
            })
          );
        });
      }
    }

    // Изменяем цвет фона кнопок завершения заданий
    if (context.model.mainForm instanceof DefaultFormTabWithTasksViewModel) {
      for (const task of context.model.mainForm.tasks) {
        task.modifyWorkspace(e => {
          const workspace = e.task.taskWorkspace;
          // Окрашиваем кнопку "ещё" в красный цвет
          workspace.moreAction.button.setStyle({ background: 'red' });
          for (const action of workspace.actions) {
            if (action.completionOption) {
              // Окрашиваем видимые кнопки завершения задания в тёмно синий цвет
              action.button.setStyle({ background: 'darkblue' });
            }
          }
          for (const action of workspace.additionalActions) {
            // Окрашиваем кнопки дополнительных действий в контекстном меню в синий цвет
            action.button.setStyle({ background: 'skyblue' });
          }
        });
      }
    }

    // Кастомизация стилей блока MainInfo
    const mainInfoBlock = context.model.blocks.get('MainInfo');
    if (mainInfoBlock) {
      mainInfoBlock.customStyle = CustomStyle.createCustomBlockStyle({
        captionFontSize: '1.2rem',
        captionIcon: getTessaIcon('Thin145'),
        captionFontColor: '#ffffff',
        captionPadding: '8px',
        captionBackgroundColor: '#63bf87cc',
        captionHoverBackgroundColor: '#63bf87cc',
        mainBackgroundColor: '#99cda4cc',
        controlsPadding: '15px'
      });
    }
  }

  public finalized(): void {
    for (const func of this._disposes) {
      if (func) {
        func();
      }
    }
    this._disposes.length = 0;

    this.clearSyncPagesEvents();
  }

  public saving(context: ICardUIExtensionContext): void {
    // Добавим ошибку валидации, если найден файл с определённым именем.
    if (context.fileContainer.files.find(x => x.name === 'show error.txt')) {
      context.validationResult.add(
        ValidationKey.unknown,
        ValidationResultType.Error,
        'File "show error.txt" was added, can\'t save the card.'
      );

      return;
    }

    // Удаляем файл с определённым именем.
    const fileToRemove = context.fileContainer.files.find(x => x.name === 'remove me.txt');
    if (fileToRemove) {
      fileToRemove.changeName('file was removed.txt');
    }
  }

  private async get1CfileAsync(): Promise<void> {
    const mainEditor = UIContext.current?.cardEditor;
    const mainModel = mainEditor?.cardModel;
    if (!mainModel) {
      return;
    }

    const dialogResult = await createDialogForm(
      'AbCarExternalSystemRequest',
      undefined,
      FormCreationOptions.AlwaysCreateTabbedForm,
      undefined,
      undefined,
      undefined,
      {
        createFileContainer: true
      }
    );
    if (!dialogResult) {
      return;
    }

    const getContentFromFile = (file: File): Promise<string> => {
      return new Promise(resolve => {
        const reader = new FileReader();
        reader.readAsArrayBuffer(file);
        reader.onloadend = async () => {
          const buffer = reader.result as ArrayBuffer;
          const str = Base64Helper.bytesToBase64(
            new Uint8Array(reader.result as ArrayBuffer, 0, buffer.byteLength)
          );
          resolve(str);
        };
      });
    };

    const [form, model] = dialogResult;
    model.mainForm = form;
    const cardEditor = createCardEditorModel();
    await cardEditor.setCardModel(model);
    await AdvancedCardDialogManager.instance.showCard({
      editor: cardEditor,
      prepareEditorAction: editor => {
        editor.cardModel?.fileContainer.containerFileChanging.addWithDispose(async e => {
          if (e.added) {
            const maxFileSize = 20; // Max file size for 1C test dialog.
            if (e.added.size / 1024 > maxFileSize) {
              await showMessage(localize('$AbTest_MaxFileSizeExceeded', maxFileSize));
              e.cancel = true;
            }
          }
        });
        editor.statusBarIsVisible = false;
        editor.toolbar.addItem(
          new CardToolbarAction({
            name: 'Ok',
            caption: '$UI_Common_OK',
            icon: 'ta icon-Int426',
            command: async _ => {
              const request = new CardRequest();
              const requestInfo = request.info;
              const testCardSection = model.card.sections.tryGet('MainInfo');

              request.requestType = '86333B21-A1C5-4698-B023-B427C8BCCF94';
              requestInfo['Name'] = createTypedField(
                testCardSection?.fields.get('Name'),
                DotNetType.String
              );
              requestInfo['Driver'] = createTypedField(
                testCardSection?.fields.get('DriverName'),
                DotNetType.String
              );
              const files = new Array<{
                name: TypedField<DotNetType.String, string>;
                content: TypedField<DotNetType.String, string>;
              }>();
              for (const file of model.fileContainer.files) {
                const content = await getContentFromFile(file.lastVersion.content!);
                const fileInfo = {
                  name: createTypedField(file.name, DotNetType.String),
                  content: createTypedField(content, DotNetType.String)
                };
                files.push(fileInfo);
              }

              requestInfo['Files'] = files;

              // показываем сплэш и задаём блокирующую операцию для карточки:
              // пользователь не сможет закрыть вкладку или отрефрешить карточку, пока она не закончится
              let response: CardResponse = new CardResponse();
              await LoadingOverlay.instance.show(async () => {
                await cardEditor.setOperationInProgress(async () => {
                  setTimeout(() => '42', 2000);
                  response = await CardService.instance.request(request);
                });
              });

              const result = response.validationResult.build();

              await showNotEmpty(result);

              if (!result.isSuccessful) {
                return;
              }

              const content = tryGetFromInfo<string>(response.info, 'Xml');
              const fileName = 'response.xml';
              const newFile = new File([content], fileName);

              const file = mainModel.fileContainer.files.find(f => f.name === fileName);
              if (file) {
                await mainModel.previewManager.resetIfInPreview(file.lastVersion);
                file.replace(new File([content], fileName), true);
              } else {
                await mainModel.fileContainer.addFile(
                  mainModel.fileContainer.createFile(newFile),
                  false,
                  true
                );
              }
              await editor.close();
            },
            order: -1
          })
        );

        editor.toolbar.addItem(
          new CardToolbarAction({
            name: 'Cancel',
            caption: '$UI_Common_Cancel',
            icon: 'ta icon-Int626',
            order: 40,
            toolTip: '$UI_Common_Cancel',
            command: async _ => {
              await editor.close();
            }
          })
        );

        editor.context.info[systemKeyPrefix + 'DialogClosingAction'] = () => Promise.resolve(false);

        return true;
      }
    });
  }

  private setPageSyncEvents(
    previewArea1: IPreviewerViewModel | null,
    previewArea2: IPreviewerViewModel | null
  ): void {
    this.clearSyncPagesEvents();

    if (
      previewArea1 &&
      previewArea2 &&
      previewArea1 instanceof PdfPreviewerViewModel &&
      previewArea2 instanceof PdfPreviewerViewModel
    ) {
      // на изменение страницы в 1 превью, меняем на такую же страницу во 2 превью.
      const control1IndexReaction = reaction(
        () => previewArea1.pageIndex,
        index => {
          previewArea2.pageIndex = index;
        }
      );

      this._syncPageEvents.push(control1IndexReaction);
    }
  }

  private clearSyncPagesEvents(): void {
    for (const f of this._syncPageEvents) {
      f();
    }
    this._syncPageEvents.length = 0;
  }

  private async executeCarTableRequest(cardId: string, asCustomRequest: boolean): Promise<void> {
    const cardEditor = UIContext.current?.cardEditor;
    if (!cardEditor) {
      return;
    }

    let data: IStorage[] | null = null;

    if (asCustomRequest) {
      // Получение данные через кастомный запрос.

      const request = new CardRequest();
      request.requestType = '249cb101-c65e-44e0-8cc4-95bbe17978bf'; // TestCarTableRequest

      // Блокировка редактирования карточки в UI до получения ответа.
      let response = new CardResponse();
      await LoadingOverlay.instance.show(async () => {
        await cardEditor.setOperationInProgress(async () => {
          response = await CardService.instance.request(request);
        });
      });

      // Отображение информации в случае ошибки и/или предупреждений.
      const result = response.validationResult.build();
      await showNotEmpty(result);
      if (!result.isSuccessful) {
        return;
      }

      data = StorageHelper.tryGet(response.info, 'CarTableRequestResult') ?? null;
    } else {
      // Получение данные через контроллер.

      try {
        data = await this._serviceClient.getCarTableRequest(cardId);
      } catch (err) {
        if (err instanceof HttpError && err.status === 404) {
          const result = ValidationResult.fromText(
            '$AbTest_CarTableRequestController_NotFound',
            ValidationResultType.Error
          );
          await showNotEmpty(result);
        }

        throw err;
      }
    }

    if (!data) {
      return;
    }

    // Создание формы типа диалога.
    const dialogResult = await createDialogForm(
      'AbCarTableRequest',
      undefined,
      undefined,
      undefined,
      async response => {
        // Копирование данных из data в секцию "Table".

        const itemsSection = response.card.sections.get('Table');
        for (const item of data!) {
          const row = itemsSection.rows.add();
          row.rowId = Guid.newGuid();

          for (const key of Object.keys(item)) {
            // Объект имеет формат полей TypedJson.

            const typedValue = item[key] as TypedField;
            row.set(key, TypedField.tryGet(typedValue), TypedField.getType(typedValue));
          }
        }
      }
    );

    // Завершение метода в случае, если не удалось создать форму диалога.
    if (!dialogResult) {
      return;
    }

    // Задание основной формы диалога.
    const [form, model] = dialogResult;
    model.mainForm = form;

    // Создание редактора карточки.
    const resultDialogEditor = createCardEditorModel();
    await resultDialogEditor.setCardModel(model);

    // Отображение карточки.
    await AdvancedCardDialogManager.instance.showCard({
      displayValue: '$AbTest_CardTypes_Tabs_CarTableRequest',
      editor: resultDialogEditor,
      prepareEditorAction: editor => {
        editor.statusBarIsVisible = false;

        editor.toolbar.addItem(
          new CardToolbarAction({
            name: 'Ok',
            caption: '$UI_Common_OK',
            icon: 'ta icon-Int426',
            command: async _ => {
              await editor.close();
            }
          })
        );

        // Задание действия при закрытии advanced-диалога.
        editor.context.info[systemKeyPrefix + 'DialogClosingAction'] = () => Promise.resolve(false);

        return true;
      }
    });
  }
}
